//! Requests: list, show, create, edit and delete the signed-in user's own (htmx: POST-only forms), one file per
//! action pair. Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.
//! Every lookup goes through `request::find_for`, so another user's id is 404.
//! APP: the spec is product/features/requests.md; cite its AC ids on the tests.

mod destroy;
mod edit;
mod index;
mod new;
mod show;

pub use destroy::destroy;
pub use edit::{edit, update};
pub use index::index;
pub use new::{create, new};
pub use show::show;

use crate::{
    error::AppError,
    models::{User, agent},
    state::AppState,
    views::requests::RequestChoices,
};

/// The `<select>` options of the form: only records the user may reference.
async fn choices(s: &AppState, user: &User) -> Result<RequestChoices, AppError> {
    Ok(RequestChoices {
        agent: agent::choices_for(&s.db, user).await?,
    })
}
